CREATE TABLE public.citations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE RESTRICT,
  quote_text text NOT NULL CHECK (char_length(btrim(quote_text)) BETWEEN 2 AND 1600),
  author text NOT NULL CHECK (char_length(btrim(author)) BETWEEN 2 AND 220),
  source_title text NULL,
  source_reference text NULL,
  source_url text NULL,
  pedagogical_explanation text NULL CHECK (pedagogical_explanation IS NULL OR char_length(btrim(pedagogical_explanation)) <= 1600),
  keywords text[] NOT NULL DEFAULT '{}'::text[],
  is_active boolean NOT NULL DEFAULT false,
  is_validated boolean NOT NULL DEFAULT false,
  created_by uuid NULL REFERENCES public.profiles(id) ON DELETE SET NULL,
  validated_by uuid NULL REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX citations_unique_source ON public.citations (subject_id, quote_text, author, COALESCE(source_title, ''));
CREATE INDEX citations_subject_visibility_idx ON public.citations (subject_id, is_active, is_validated);
CREATE INDEX citations_author_lower_idx ON public.citations (lower(author));
CREATE INDEX citations_keywords_gin_idx ON public.citations USING gin (keywords);

CREATE TABLE public.citation_scopes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  citation_id uuid NOT NULL REFERENCES public.citations(id) ON DELETE CASCADE,
  level_id uuid NOT NULL REFERENCES public.levels(id) ON DELETE RESTRICT,
  series_id uuid NULL REFERENCES public.series(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX citation_scopes_unique_target ON public.citation_scopes (citation_id, level_id, COALESCE(series_id, '00000000-0000-0000-0000-000000000000'::uuid));
CREATE INDEX citation_scopes_access_idx ON public.citation_scopes (level_id, series_id, citation_id);

CREATE TABLE public.citation_themes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  citation_id uuid NOT NULL REFERENCES public.citations(id) ON DELETE CASCADE,
  theme text NOT NULL CHECK (char_length(btrim(theme)) BETWEEN 2 AND 120),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT citation_themes_unique UNIQUE (citation_id, theme)
);
CREATE INDEX citation_themes_theme_lower_idx ON public.citation_themes (lower(theme));

CREATE TABLE public.mentor_conversations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 160),
  subject text NULL CHECK (subject IS NULL OR char_length(btrim(subject)) <= 120),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX mentor_conversations_user_updated_idx ON public.mentor_conversations (user_id, updated_at DESC);

CREATE TABLE public.mentor_conversation_messages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id uuid NOT NULL REFERENCES public.mentor_conversations(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  role text NOT NULL CHECK (role IN ('user', 'assistant')),
  content text NOT NULL CHECK (char_length(btrim(content)) BETWEEN 1 AND 6000),
  attachment_label text NULL CHECK (attachment_label IS NULL OR char_length(btrim(attachment_label)) <= 480),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX mentor_conversation_messages_conversation_idx ON public.mentor_conversation_messages (conversation_id, created_at);
CREATE INDEX mentor_conversation_messages_user_idx ON public.mentor_conversation_messages (user_id, created_at);

CREATE UNIQUE INDEX edutech_favorites_citation_unique ON public.edutech_favorites (user_id, content_type, content_id) WHERE content_type = 'citation';

ALTER TABLE public.citations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.citation_scopes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.citation_themes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mentor_conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mentor_conversation_messages ENABLE ROW LEVEL SECURITY;

CREATE POLICY citations_admin_all ON public.citations FOR ALL USING ((SELECT public.is_edutech_admin())) WITH CHECK ((SELECT public.is_edutech_admin()));
CREATE POLICY citations_student_select ON public.citations FOR SELECT USING (is_active IS TRUE AND is_validated IS TRUE AND EXISTS (SELECT 1 FROM public.citation_scopes scope JOIN public.profiles profile ON profile.id = auth.uid() WHERE scope.citation_id = citations.id AND scope.level_id = profile.level_id AND (scope.series_id IS NULL OR scope.series_id = profile.series_id)));

CREATE POLICY citation_scopes_admin_all ON public.citation_scopes FOR ALL USING ((SELECT public.is_edutech_admin())) WITH CHECK ((SELECT public.is_edutech_admin()));
CREATE POLICY citation_scopes_student_select ON public.citation_scopes FOR SELECT USING (EXISTS (SELECT 1 FROM public.profiles profile WHERE profile.id = auth.uid() AND citation_scopes.level_id = profile.level_id AND (citation_scopes.series_id IS NULL OR citation_scopes.series_id = profile.series_id)));

CREATE POLICY citation_themes_admin_all ON public.citation_themes FOR ALL USING ((SELECT public.is_edutech_admin())) WITH CHECK ((SELECT public.is_edutech_admin()));
CREATE POLICY citation_themes_student_select ON public.citation_themes FOR SELECT USING (EXISTS (SELECT 1 FROM public.citations citation WHERE citation.id = citation_themes.citation_id));

CREATE POLICY mentor_conversations_self ON public.mentor_conversations FOR ALL USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE POLICY mentor_conversation_messages_self ON public.mentor_conversation_messages FOR ALL USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.mentor_conversations conversation WHERE conversation.id = mentor_conversation_messages.conversation_id AND conversation.user_id = auth.uid())) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.mentor_conversations conversation WHERE conversation.id = mentor_conversation_messages.conversation_id AND conversation.user_id = auth.uid()));

CREATE OR REPLACE FUNCTION public.touch_mentor_conversation_updated_at() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN UPDATE public.mentor_conversations SET updated_at = now() WHERE id = NEW.conversation_id AND user_id = NEW.user_id; RETURN NEW; END; $$;
CREATE TRIGGER mentor_conversation_messages_touch AFTER INSERT ON public.mentor_conversation_messages FOR EACH ROW EXECUTE FUNCTION public.touch_mentor_conversation_updated_at();

INSERT INTO public.citations (subject_id, quote_text, author, source_title, source_reference, source_url, pedagogical_explanation, keywords, is_active, is_validated)
SELECT subject.id, seed.quote_text, seed.author, seed.source_title, seed.source_reference, seed.source_url, seed.pedagogical_explanation, seed.keywords, true, true
FROM (VALUES
  ('Français', 'Travaillez, prenez de la peine : C’est le fonds qui manque le moins.', 'Jean de La Fontaine', 'Fables', 'Livre V, « Le Laboureur et ses enfants »', 'https://fr.wikisource.org/wiki/Fables_de_La_Fontaine_(%C3%A9d._1874)/Le_Laboureur_et_ses_enfants', 'Cette morale valorise l’effort régulier. Elle peut servir dans une rédaction ou une argumentation sur le travail, l’éducation et la réussite.', ARRAY['travail','effort','réussite','éducation']::text[]),
  ('Philosophie', 'Le bon sens est la chose du monde la mieux partagée.', 'René Descartes', 'Discours de la méthode', 'Première partie', 'https://fr.wikisource.org/wiki/Discours_de_la_m%C3%A9thode_(%C3%A9d._Cousin)/Premi%C3%A8re_partie', 'Cette formule introduit une réflexion sur la raison, le jugement et l’égalité des êtres humains face à la pensée.', ARRAY['raison','jugement','vérité','bon sens']::text[]),
  ('Histoire-Géographie', 'Les hommes naissent et demeurent libres et égaux en droits.', 'Assemblée nationale constituante', 'Déclaration des droits de l’homme et du citoyen de 1789', 'Article premier', 'https://fr.wikisource.org/wiki/D%C3%A9claration_des_Droits_de_l%E2%80%99Homme_et_du_Citoyen_de_1789', 'Cette affirmation sert à analyser les principes des droits de l’homme, de l’égalité juridique et des héritages de la Révolution française.', ARRAY['droits','égalité','liberté','révolution française']::text[]),
  ('Physique-Chimie', 'Dans les champs de l’observation, le hasard ne favorise que les esprits préparés.', 'Louis Pasteur', 'Discours à l’Université de Lille', '1854 ; reproduit dans les Œuvres de Pasteur', 'https://commons.wikimedia.org/wiki/File:Louis_Pasteur_Universit%C3%A9_de_Lille_1854-1857_dans_les_champs_de_l%27observation_le_hasard_ne_favorise_que_les_esprits_pr%C3%A9par%C3%A9s.pdf', 'Cette citation rappelle que l’observation, la rigueur et la préparation sont essentielles dans une démarche scientifique.', ARRAY['observation','méthode scientifique','rigueur','expérience']::text[])
) AS seed(subject_name, quote_text, author, source_title, source_reference, source_url, pedagogical_explanation, keywords)
JOIN public.subjects subject ON subject.name = seed.subject_name
ON CONFLICT DO NOTHING;

INSERT INTO public.citation_scopes (citation_id, level_id, series_id)
SELECT citation.id, level.id, NULL
FROM public.citations citation
JOIN public.subjects subject ON subject.id = citation.subject_id
CROSS JOIN public.levels level
WHERE subject.name IN ('Français', 'Philosophie', 'Histoire-Géographie', 'Physique-Chimie') AND level.name IN ('Première', 'Terminale')
ON CONFLICT DO NOTHING;

INSERT INTO public.citation_themes (citation_id, theme)
SELECT citation.id, theme_seed.theme
FROM public.citations citation
JOIN public.subjects subject ON subject.id = citation.subject_id
JOIN (VALUES
  ('Français', 'Travail'), ('Français', 'Effort'),
  ('Philosophie', 'Raison'), ('Philosophie', 'Vérité'),
  ('Histoire-Géographie', 'Liberté'), ('Histoire-Géographie', 'Égalité'),
  ('Physique-Chimie', 'Observation'), ('Physique-Chimie', 'Démarche scientifique')
) AS theme_seed(subject_name, theme) ON theme_seed.subject_name = subject.name
ON CONFLICT DO NOTHING;
